import{ac as t}from"./index-CFxbdIWE.js";const o={list(e){return t.get("/enrollments",e)},generate(e){return t.post("/enrollments/generate",{semester_id:e})},updateAdvisorAndQuota(e,r){return t.put(`/enrollments/${e}/advisor-quota`,r)},get(e){return t.get(`/enrollments/${e}`)},create(e){return t.post("/enrollments",e)},getStudentEnrollments(e){return t.get(`/students/${e}/enrollments`)},storeStudentEnrollment(e,r){return t.post(`/students/${e}/enrollments`,r)},getItems(e){return t.get(`/enrollments/${e}/items`)},addItem(e,r,n){return t.post(`/enrollments/${e}/items`,{class_id:Number(r),notes:n})},removeItem(e,r){return t.delete(`/enrollments/${e}/items/${r}`)},submit(e){return t.post(`/enrollments/${e}/submit`)},approve(e,r){return t.post(`/enrollments/${e}/approve`,{notes:r})},reject(e,r){return t.post(`/enrollments/${e}/reject`,{reason:r})},requestRevision(e,r){return t.post(`/enrollments/${e}/request-revision`,{notes:r})},lock(e){return t.post(`/enrollments/${e}/lock`)},loadPackage(e,r){return t.post(`/enrollments/${e}/load-package`,{krs_package_id:r})}};export{o as e};
